eg,#70e7ff22 1px,transparent 1px);background-size:42px 42px;animation:gridpan 7s linear infinite}\n@keyframes drift{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}\n@keyframes gridpan{to{background-position:42px 42px}}\n.hud{display:none;position:absolute;top:15px;left:15px;right:15px;justify-content:space-between;z-index:20;color:var(--muted);font-size:12px}.hud span{padding:7px 10px;background:#03080ccc;border:1px solid #70e7ff18;border-radius:7px}\n.progress{position:absolute;top:0;left:0;right:0;display:none;gap:4px;padding:12px 16px;z-index:25}.progress.on{display:flex}.seg{flex:1;height:3px;background:#70e7ff22;border-radius:2px;transition:background .3s ease}.seg.done{background:var(--cyan)}\n#boot{text-align:left}.terminal{background:#02070a;border:1px solid #70e7ff22;border-radius:10px;padding:17px;line-height:1.7}.center{text-align:center}\n.core-space{position:absolute;width:min(80vw,720px);height:70vh;left:50%;top:50%;transform:translate(-50%,-50%);perspective:900px;touch-action:none;cursor:grab;user-select:none}.core-space:active{cursor:grabbing}.core{position:absolute;left:50%;top:50%;width:190px;height:190px;transform-style:preserve-3d;transform:translate(-50%,-50%) rotateX(-18deg) rotateY(25deg);transition:.35s}.core.dragging{transition:none}\n.face{position:absolute;inset:0;border:1px solid #70e7ff3d;background:#70e7ff04}.f1{transform:translateZ(95px)}.f2{transform:rotateY(180deg) translateZ(95px)}.f3{transform:rotateY(90deg) translateZ(95px)}.f4{transform:rotateY(-90deg) translateZ(95px)}.f5{transform:rotateX(90deg) translateZ(95px)}.f6{transform:rotateX(-90deg) translateZ(95px)}\n.node{position:absolute;width:20px;height:20px;border-radius:50%;background:var(--cyan);box-shadow:0 0 12px var(--cyan),0 0 35px #70e7ff44;transition:background .3s ease,box-shadow .3s ease,transform .3s ease}.off{background:#18262d;box-shadow:none;border:1px solid #40515a}.glitch{background:var(--red);box-shadow:0 0 20px var(--red);animation:g .1s infinite alternate}@keyframes g{to{transform:translate(4px,-3px) skewX(8deg)}}\n.n0{left:0;top:0}.n1{right:0;top:0}.n2{right:0;bottom:0}.n3{left:0;bottom:0}.n4{left:0;top:0;transform:translateZ(190px)}.n5{right:0;top:0;transform:translateZ(190px)}.n6{right:0;bottom:0;transform:translateZ(190px)}.n7{left:0;bottom:0;transform:translateZ(190px)}\n.corelabel{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) translateZ(125px);font-size:22px;color:#fff;letter-spacing:.2em}\n.readout{position:absolute;left:50%;bottom:9%;transform:translateX(-50%);text-align:center}.big{font-size:clamp(38px,9vw,86px);color:#fff;text-shadow:0 0 30px #70e7ff33;font-weight:800}.controls{position:absolute;bottom:17px;left:50%;transform:translateX(-50%);color:var(--muted);font-size:12px;text-align:center;width:92vw}\n.title{color:var(--cyan);letter-spacing:.16em;margin-bottom:18px}.value{text-align:center;font-size:clamp(40px,9vw,90px);margin:18px 0;font-weight:800}.metric{display:flex;gap:25px;justify-content:center;flex-wrap:wrap;color:var(--muted)}.metric b{color:#e8fcff}\n.duck{white-space:pre;text-align:center;color:var(--amber);font-size:20px;line-height:1.05;margin:18px}.warn{color:var(--red)}.glitchtext{animation:txt .12s infinite alternate}@keyframes txt{to{transform:translateX(3px);filter:hue-rotate(30deg)}}\n.bits{display:flex;justify-content:center;gap:7px;flex-wrap:wrap;margin:22px 0}.bit{width:54px;padding:9px 3px;cursor:pointer;border:1px solid #70e7ff33;background:#07131d;border-radius:8px}.bit.on{border-color:var(--green);box-shadow:0 0 18px #91ffb31c}.weight{display:block;color:var(--muted);font-size:10px}.digit{font-size:24px;color:#eaffff}\n.commit{padding:13px 15px;margin:9px 0;border-left:3px solid var(--cyan);background:#030a0f;border-top:1px solid #70e7ff18;border-right:1px solid #70e7ff18;border-bottom:1px solid #70e7ff18}.sha{color:#58727e}.msg{margin-top:5px}.row{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:22px}\n.end{text-align:center;font-size:clamp(25px,5vw,50px);line-height:1.35;letter-spacing:.08em;font-weight:800}\n@media(max-width:600px){.core{width:150px;height:150px}.f1{transform:translateZ(75px)}.f2{transform:rotateY(180deg) translateZ(75px)}.f3{transform:rotateY(90deg) translateZ(75px)}.f4{transform:rotateY(-90deg) translateZ(75px)}.f5{transform:rotateX(90deg) translateZ(75px)}.f6{transform:rotateX(-90deg) translateZ(75px)}}\n</style></head>\n<body>\n<div id="stars"></div><div id="grid"></div>\n<div id="hud" class="hud"><span id="hs"></span><span id="hc"></span></div>\n<div id="progress" class="progress"></div>\n\n<section id="gate" class="screen on"><div class="card gate">\n<div class="brand">BYTE//8</div><div class="sub" id="gateSub"></div>\n<div class="langs"><button class="lang" data-l="en">[ E ] English</button><button class="lang" data-l="de">[ D ] Deutsch</button><button class="lang" data-l="fa">[ F ] فارسی</button></div>\n</div></section>\n\n<section id="boot" class="screen"><div class="card"><div class="brand">BYTE//8</div><div id="bootlog" class="terminal" style="margin-top:20px"></div></div></section>\n<section id="main" class="screen"><div class="core-space"><div id="core" class="core">\n<div class="face f1"></div><div class="face f2"></div><div class="face f3"></div><div class="face f4"></div><div class="face f5"></div><div class="face f6"></div>\n<div class="node n0"></div><div class="node n1"></div><div class="node n2"></div><div class="node n3"></div><div class="node n4"></div><div class="node n5"></div><div class="node n6"></div><div class="node n7"></div><div class="corelabel">BYTE</div></div></div>\n<div class="readout"><div id="mainval" class="big">0x100</div><div id="maininfo" class="muted"></div><button id="mainNext" class="btn" style="margin-top:16px"></button></div><div id="controls" class="controls"></div></section>\n\n<section id="layer" class="screen"><div id="layerbox" class="card"></div></section>\n<section id="stack" class="screen"><div id="stackbox" class="card"></div></section>\n<section id="commit" class="screen"><div id="commitbox" class="card"></div></section>\n<section id="blame" class="screen"><div id="blamebox" class="card"></div></section>\n<section id="env" class="screen"><div id="envbox" class="card"></div></section>\n<section id="final" class="screen"><div id="finalbox" class="card"></div></section>\n\n<script>\nconst L={\nen:{sub:"A tiny interactive machine for Programmers\' Day.",det:"8 NODES DETECTED",unst:"1 NODE UNSTABLE",boot:"BOOT SEQUENCE",hex:"HEX",dec:"DECIMAL",oct:"OCTAL",bin:"BINARY",ctrl:"← → rotate · ↑ ↓ tilt · + / − zoom · ENTER continue",rotate:"Rotate the core. Press ENTER.",next:"ENTER // continue",mismatch:"REPRESENTATION MISMATCH",debug:"DEBUGGING...",duck:"Did you change something?",stack:"FATAL ERROR",so:"STACK OVERFLOW",rec:"recursion",machine:"Maybe don\'t call yourself that many times.",unwind:"ENTER // unwind one frame",locked:"VALUE LOCKED",impossible:"ERROR: 256 DOES NOT FIT IN 8 BITS.",fits:"A byte has 8 bits. That makes 256 possible states: 0 — 255.",max:"MAXIMUM VALUE OF ONE BYTE",commits:"COMMIT HISTORY",blame:"WHO DID THIS?",runblame:"RUNNING git blame...",conclusion:"CONCLUSION: It was you.",feature:"BUG DETECTED",fix:"FIX IT",feat:"CALL IT A FEATURE",accepted:"FEATURE ACCEPTED ✓",mgmt:"Excellent. You are now management material.",newbug:"NEW BUG CREATED",endian:"ENDianness",data:"DATA",big:"BIG ENDIAN",little:"LITTLE ENDIAN",att:"Same bytes. Different attitude.",load:"LOADING...",nothing:"Loading complete. Nothing was loaded.",env:"ENVIRONMENT ERROR",where:"Where did it work?",laptop:"On my laptop",machine2:"On my machine",cloud:"Probably in the cloud",old:"On my old setup",clouderr:"Cloud not found. Look outside.",notmachine:"This is not your machine.",script:"SCRIPT SIZE",times:"times the size of a single byte",first:"A computer from the early days would probably need a second computer just to complain about this one.",happy:"HAPPY PROGRAMMERS\' DAY",replay:"R // r